                        private enum CodingKeys: String, CodingKey {
                            case amount
                            case description
                            case quantity
                        }

                        public init(
                            amount: Int? = nil,
                            description: String? = nil,
                            quantity: Int? = nil
                        ) {
                            self.amount = amount
                            self.description = description
                            self.quantity = quantity
                        }
                    }
                }
            }
        }
    }
}
